args.command:
perl -e '
use strict;
use warnings;
use File::Find;

my @decls;
File::Find::find(sub {
  return unless /\.go$/ && !/_test\.go$/;
  my $path = $File::Find::name;
  open my $fh, "<", $path or return;
  my $i = 0;
  while (my $line = <$fh>) {
    $i++;
    if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\(/) {
      my ($recv, $name) = ($1, $2);
      my $recv_type = "";
      if (defined $recv && $recv ne "") {
        my @p = split(/\s+/, $recv);
        $recv_type = $p[-1];
        $recv_type =~ s/^\*//;
      }
      push @decls, [$name, $recv_type, $path, $i];
    }
  }
}, "/bench/repo/internal");

print "Total declarations: ", scalar(@decls), "\n";
print "All declarations:\n";
for my $d (sort { $a->[0] cmp $b->[0] || $a->[2] cmp $b->[2] } @decls) {
  my ($name, $recv, $path, $line) = @$d;
  $path =~ s{^/bench/repo/}{};
  my $recv_s = $recv ? "($recv)." : "";
  print "  $recv_s$name — $path:$line\n";
}
'

find /bench/repo/internal -name '*.go' ! -name '*_test.go' -print0 | xargs -0 perl -ne '
  if (/^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\(/) {
    my $recv = $1 // "";
    my $name = $2;
    my $recv_type = "";
    if ($recv ne "") {
      my @p = split(/\s+/, $recv);
      $recv_type = $p[-1];
      $recv_type =~ s/^\*//;
    }
    print "$name\t$recv_type\t$ARGV\t$.\n";
  }
  close ARGV if eof;
'

